{"content":"-- ROLES ---------------------------------------------------------------
CREATE TYPE public.app_role AS ENUM ('admin', 'sales', 'customer');

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$
LANGUAGE plpgsql SET search_path = public;

CREATE TABLE public.customers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  account_number TEXT UNIQUE,
  default_markup NUMERIC(8,4),
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.customers TO authenticated;
GRANT ALL ON public.customers TO service_role;
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.profiles (
  id UUID PRIMARY KEY,
  email TEXT,
  full_name TEXT,
  customer_id UUID REFERENCES public.customers(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.user_roles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  role public.app_role NOT NULL,
  expires_at TIMESTAMPTZ,
  granted_by UUID,
  reason TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id, role)
);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role public.app_role)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
      AND (expires_at IS NULL OR expires_at > now())
  )
$$;

CREATE OR REPLACE FUNCTION public.is_staff(_user_id UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT public.has_role(_user_id, 'admin') OR public.has_role(_user_id, 'sales')
$$;

-- PRODUCT MASTER + COST -------------------------------------------------
CREATE TABLE public.products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  manufacturer TEXT,
  mfr_part_number TEXT,
  pickrel_sku TEXT,
  category TEXT,
  uom TEXT NOT NULL DEFAULT 'EA',
  availability TEXT NOT NULL DEFAULT 'in-stock',
  list_cost NUMERIC(12,4),
  cost_multiplier NUMERIC(8,4) NOT NULL DEFAULT 1,
  net_cost NUMERIC(12,4),
  default_markup NUMERIC(8,4),
  cost_basis NUMERIC(12,4) GENERATED ALWAYS AS (COALESCE(net_cost, list_cost * cost_multiplier)) STORED,
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.customer_product_pricing (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id UUID NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
  product_id UUID REFERENCES public.products(id) ON DELETE CASCADE,
  markup NUMERIC(8,4),
  negotiated_price NUMERIC(12,4),
  note TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (customer_id, product_id)
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.customer_product_pricing TO authenticated;
GRANT ALL ON public.customer_product_pricing TO service_role;
ALTER TABLE public.customer_product_pricing ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.pricing_settings (
  id BOOLEAN PRIMARY KEY DEFAULT true CHECK (id),
  guest_markup NUMERIC(8,4) NOT NULL DEFAULT 1.45,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE ON public.pricing_settings TO authenticated;
GRANT ALL ON public.pricing_settings TO service_role;
ALTER TABLE public.pricing_settings ENABLE ROW LEVEL SECURITY;
INSERT INTO public.pricing_settings (id, guest_markup) VALUES (true, 1.45);

CREATE TABLE public.pricing_elevation_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  requested_by UUID NOT NULL,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  reviewed_by UUID,
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE ON public.pricing_elevation_requests TO authenticated;
GRANT ALL ON public.pricing_elevation_requests TO service_role;
ALTER TABLE public.pricing_elevation_requests ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.pricing_audit (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id UUID,
  entity_type TEXT NOT NULL,
  entity_id UUID,
  entity_label TEXT,
  action TEXT NOT NULL,
  changes JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT ON public.pricing_audit TO authenticated;
GRANT ALL ON public.pricing_audit TO service_role;
ALTER TABLE public.pricing_audit ENABLE ROW LEVEL SECURITY;

-- POLICIES --------------------------------------------------------------
CREATE POLICY "staff read products" ON public.products FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "admin insert products" ON public.products FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admin update products" ON public.products FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admin delete products" ON public.products FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "staff read customers" ON public.customers FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "admin write customers" ON public.customers FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "staff read cpp" ON public.customer_product_pricing FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "admin write cpp" ON public.customer_product_pricing FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "staff read settings" ON public.pricing_settings FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "admin write settings" ON public.pricing_settings FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "staff read audit" ON public.pricing_audit FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));

CREATE POLICY "own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY "own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE POLICY "own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());

CREATE POLICY "read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_staff(auth.uid()));

CREATE POLICY "staff read elevation" ON public.pricing_elevation_requests FOR SELECT TO authenticated USING (requested_by = auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY "sales create elevation" ON public.pricing_elevation_requests FOR INSERT TO authenticated WITH CHECK (requested_by = auth.uid() AND public.is_staff(auth.uid()));
CREATE POLICY "admin update elevation" ON public.pricing_elevation_requests FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));

-- PRICE RESOLUTION ------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calc_selling_price(_product_id UUID, _customer_id UUID)
RETURNS NUMERIC LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT CASE
    WHEN cpp.negotiated_price IS NOT NULL THEN cpp.negotiated_price
    WHEN p.cost_basis IS NULL THEN NULL
    ELSE round(p.cost_basis * COALESCE(cpp.markup, c.default_markup, p.default_markup, s.guest_markup), 2)
  END
  FROM public.products p
  LEFT JOIN public.customers c ON c.id = _customer_id
  LEFT JOIN public.customer_product_pricing cpp
    ON cpp.product_id = p.id AND cpp.customer_id = _customer_id
  CROSS JOIN (SELECT guest_markup FROM public.pricing_settings LIMIT 1) s
  WHERE p.id = _product_id
$$;

CREATE OR REPLACE FUNCTION public.price_list(_customer_id UUID)
RETURNS TABLE (slug TEXT, price NUMERIC, uom TEXT, availability TEXT, mfr_part_number TEXT, pickrel_sku TEXT)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT p.slug, public.calc_selling_price(p.id, _customer_id), p.uom, p.availability, p.mfr_part_number, p.pickrel_sku
  FROM public.products p
  WHERE p.active
$$;

-- AUDIT -----------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.log_pricing_change()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  changed JSONB := '{}'::jsonb;
  k TEXT;
  oldj JSONB;
  newj JSONB;
  label TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    oldj := to_jsonb(OLD); newj := '{}'::jsonb;
  ELSIF TG_OP = 'INSERT' THEN
    oldj := '{}'::jsonb; newj := to_jsonb(NEW);
  ELSE
    oldj := to_jsonb(OLD); newj := to_jsonb(NEW);
  END IF;

  FOR k IN SELECT jsonb_object_keys(COALESCE(NULLIF(newj, '{}'::jsonb), oldj)) LOOP
    IF k IN ('updated_at','created_at') THEN CONTINUE; END IF;
    IF (oldj -> k) IS DISTINCT FROM (newj -> k) THEN
      changed := changed || jsonb_build_object(k, jsonb_build_object('from', oldj -> k, 'to', newj -> k));
    END IF;
  END LOOP;

  IF changed = '{}'::jsonb THEN RETURN COALESCE(NEW, OLD); END IF;

  label := COALESCE(newj ->> 'name', oldj ->> 'name', newj ->> 'slug', oldj ->> 'slug', TG_TABLE_NAME);

  INSERT INTO public.pricing_audit (actor_id, entity_type, entity_id, entity_label, action, changes)
  VALUES (auth.uid(), TG_TABLE_NAME, COALESCE((newj ->> 'id')::uuid, (oldj ->> 'id')::uuid), label, TG_OP, changed);

  RETURN COALESCE(NEW, OLD);
END; $$;

CREATE TRIGGER audit_products AFTER INSERT OR UPDATE OR DELETE ON public.products
FOR EACH ROW EXECUTE FUNCTION public.log_pricing_change();
CREATE TRIGGER audit_customers AFTER INSERT OR UPDATE OR DELETE ON public.customers
FOR EACH ROW EXECUTE FUNCTION public.log_pricing_change();
CREATE TRIGGER audit_cpp AFTER INSERT OR UPDATE OR DELETE ON public.customer_product_pricing
FOR EACH ROW EXECUTE FUNCTION public.log_pricing_change();
CREATE TRIGGER audit_settings AFTER UPDATE ON public.pricing_settings
FOR EACH ROW EXECUTE FUNCTION public.log_pricing_change();
CREATE TRIGGER audit_roles AFTER INSERT OR UPDATE OR DELETE ON public.user_roles
FOR EACH ROW EXECUTE FUNCTION public.log_pricing_change();

CREATE TRIGGER products_updated BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER customers_updated BEFORE UPDATE ON public.customers FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER cpp_updated BEFORE UPDATE ON public.customer_product_pricing FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
